import styled from '@emotion/styled';
import { StyledExportPageSection } from 'shared/Styles/exportPages.styles';
import { theme } from 'theme';

export const StyledSummaryTocCardHeader = styled.div({
  display: 'flex',
  alignItems: 'center',
  gap: '8px',
  flex: 1,
  minWidth: 0,
});

export const StyledSummaryTocCardHeaderFlag = styled.img({
  width: '24px',
  height: '24px',
  minWidth: '24px',
  minHeight: '24px',
  borderRadius: '50%',
  objectFit: 'cover',
});

export const StyledSummaryTocCardHeaderTitle = styled.span({
  fontFamily: theme.fonts.paragraph,
  fontSize: '18px',
  fontWeight: 700,
  color: theme.colors.txt.default,
  lineHeight: '140%',
});

export const StyledSummaryAgendaSection = styled(StyledExportPageSection)({
  minHeight: 'auto',
  height: 'fit-content',
});
